var img;
var squares = []

var grid = 12;
var count = 20;

function setup() {
	createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight));
	background("white");
	img = get();
	stroke("black");
	strokeWeight(9);
	strokeJoin(ROUND);
	strokeCap(PROJECT);
	pixelDensity(1);

	squares = []
	for (let i = 0; i < count; i++) {
		let xs = floor(random(1, 3));
		let ys = floor(random(1, 3));
		let x = floor(random(0, grid - xs));
		let y = floor(random(0, grid - ys));
		let c = floor(random(4));
		let a = floor(random(50, 100));
		squares.push({
			x: x,
			y: y,
			x_size: xs,
			y_size: ys,
			color: c,
			age: a
		})
	}
}

function draw() {
	push();
	translate(width / 2, height / 2);
	rotate(0.001 * sin(millis() / 10000));
	translate(-width / 2, -height / 2);
	image(img, 4, 4, width - 8, height - 8, 0, 0, width, height);
	pop();
	filter(POSTERIZE, 15);

	let cell = floor(0.95 * width / grid);
	let offset = floor(width - cell * grid);

	for (let i = 0; i < squares.length; i++) {
		if (squares[i].age <= 0) {
			var xs = floor(random(1, 3));
			var ys = floor(random(1, 3));
			var x = floor(random(0, grid - xs));
			var y = floor(random(0, grid - ys));
			var c = floor(random(4));
			var a = floor(random(50, 100));
			squares[i] = {
				x: x,
				y: y,
				x_size: xs,
				y_size: ys,
				color: c,
				age: a
			}
		}

		switch (squares[i].color) {
			case 0:
				fill("red");
				break;
			case 1:
				fill("blue");
				break;
			case 2:
				fill("yellow");
				break;
			case 3:
				fill("white");
				break;
		}

		if (random(1) < 0.001) {
			line(offset / 2, offset + squares[i].y * cell, offset + (grid - 0.5) * cell, offset + squares[i].y * cell);
			line(offset / 2, offset + (squares[i].y + squares[i].y_size) * cell, offset + (grid - 0.5) * cell, offset + (squares[i].y + squares[i].y_size) * cell);
			line(offset + squares[i].x * cell, offset / 2, offset + squares[i].x * cell, offset + (grid - 0.5) * cell);
			line(offset + (squares[i].x + squares[i].x_size) * cell, offset / 2, offset + (squares[i].x + squares[i].x_size) * cell, offset + (grid - 0.5) * cell);
		}

		rect(offset + squares[i].x * cell, offset + squares[i].y * cell, squares[i].x_size * cell, squares[i].y_size * cell);

		squares[i].age--;



	}

	img = get();

}

//disable default right mouse click
document.addEventListener("contextmenu", (event) => event.preventDefault(), "true")

//left click restarts, right click does an image capture
var lapse = 0; // mouse timer
function mousePressed() {
	if (millis() - lapse > 400) {
		lapse = millis();
		if (mouseButton === RIGHT) {
			save("img_" + year() + nf(month(), 2) + nf(day(), 2) + nf(hour(), 2) + nf(minute(), 2) + nf(second(), 2) + ".png");
		} else if (mouseButton === CENTER) {} else {
			setup(); // start a new image
		}
	}
	return (false)
}
